sys_ui_policy.script_true:
function onCondition() {
    function setTabVisibility(answer) {
        var current_user = g_user.userID;
        var is_rw_member = answer;

        if (g_user.hasRole("admin")) { //Admin override
            g_form.setSectionDisplay("comments_andworknotes", true);
            g_form.setSectionDisplay("subcases_andtasks", true);
            g_form.setSectionDisplay("case_information", true);
            g_form.setSectionDisplay("initial_review", true);
            g_form.setSectionDisplay("negotiated_resolution", true);
            g_form.setSectionDisplay("mediation", true);
            g_form.setSectionDisplay("investigation", true);
            g_form.setSectionDisplay("preventative_measuresohssection", true);
            g_form.setSectionDisplay("rw", true);
        } else if (g_form.getValue("assigned_to") === current_user) { //Manager handling the case
            g_form.setSectionDisplay("comments_andworknotes", true);
            g_form.setSectionDisplay("subcases_andtasks", true);
            g_form.setSectionDisplay("case_information", true);
            g_form.setSectionDisplay("initial_review", true);
            g_form.setSectionDisplay("negotiated_resolution", true);
            g_form.setSectionDisplay("mediation", true);
            g_form.setSectionDisplay("investigation", true);
            g_form.setSectionDisplay("preventative_measuresohssection", true);
            g_form.setSectionDisplay("rw", false);
        } else if (is_rw_member === 'true') { // RW
            g_form.setSectionDisplay("comments_andworknotes", true);
            g_form.setSectionDisplay("subcases_andtasks", true);
            g_form.setSectionDisplay("case_information", true);
            g_form.setSectionDisplay("initial_review", true);
            g_form.setSectionDisplay("negotiated_resolution", true);
            g_form.setSectionDisplay("mediation", true);
            g_form.setSectionDisplay("investigation", true);
            g_form.setSectionDisplay("preventative_measuresohssection", true);
            g_form.setSectionDisplay("rw", true);
        } else if (g_user.hasRole("x_hccc_hoc_ohs.admin")) { // OHS admin
            g_form.setSectionDisplay("comments_andworknotes", false);
            g_form.setSectionDisplay("subcases_andtasks", false);
            g_form.setSectionDisplay("case_information", false);
            g_form.setSectionDisplay("initial_review", true);
            g_form.setSectionDisplay("negotiated_resolution", true);
            g_form.setSectionDisplay("mediation", false);
            g_form.setSectionDisplay("investigation", false);
            g_form.setSectionDisplay("preventative_measuresohssection", true);
            g_form.setSectionDisplay("rw", false);
		} else if (g_user.hasRole("x_hccc_hoc_ohs.advisor")) { // OHS advisor
            g_form.setSectionDisplay("comments_andworknotes", false);
            g_form.setSectionDisplay("subcases_andtasks", false);
            g_form.setSectionDisplay("case_information", false);
            g_form.setSectionDisplay("initial_review", false);
            g_form.setSectionDisplay("negotiated_resolution", false);
            g_form.setSectionDisplay("mediation", false);
            g_form.setSectionDisplay("investigation", false);
            g_form.setSectionDisplay("preventative_measuresohssection", true);
            g_form.setSectionDisplay("rw", false);
        } else if (g_user.hasRole("x_hccc_hoc_ohs.committee")) { // Building committee
            g_form.setSectionDisplay("comments_andworknotes", false);
            g_form.setSectionDisplay("subcases_andtasks", false);
            g_form.setSectionDisplay("case_information", false);
            g_form.setSectionDisplay("initial_review", false);
            g_form.setSectionDisplay("negotiated_resolution", false);
            g_form.setSectionDisplay("mediation", false);
            g_form.setSectionDisplay("investigation", false);
            g_form.setSectionDisplay("preventative_measuresohssection", true);
            g_form.setSectionDisplay("rw", false);
        } else { //Manager not handling the case and other users
            g_form.setSectionDisplay("comments_andworknotes", false);
            g_form.setSectionDisplay("subcases_andtasks", false);
            g_form.setSectionDisplay("case_information", false);
            g_form.setSectionDisplay("initial_review", false);
            g_form.setSectionDisplay("negotiated_resolution", false);
            g_form.setSectionDisplay("mediation", false);
            g_form.setSectionDisplay("investigation", false);
            g_form.setSectionDisplay("preventative_measuresohssection", false);
            g_form.setSectionDisplay("rw", false);
        }


        g_form.setSectionDisplay("subcases_andtasks", false); //Tab currently deactivated for all users pending feature enhancement

    }

    var current_user = g_user.userID;
    var rw_group_sys_id = 'b4a1b2c2db927c109b09e6fa4b961983';

    var ga = new GlideAjax('x_hccc_hoc_ohs.HoCOHSMUtils');
    ga.addParam('sysparm_name', 'checkUserInGroup');
    ga.addParam('user_id', current_user);
    ga.addParam('group_id', rw_group_sys_id);

    ga.getXMLAnswer(setTabVisibility);


}
